begin;
select no_plan();
insert into auth.users(id,email) values('ac100000-0000-0000-0000-000000000001','owner@inbox.test'),('ac100000-0000-0000-0000-000000000002','desk@inbox.test'),('ac100000-0000-0000-0000-000000000003','hk@inbox.test');
insert into public.tenants(id,name,slug) values('ac200000-0000-0000-0000-000000000001','Inbox Business','inbox-business');
insert into public.properties(id,tenant_id,name,property_type) values('ac300000-0000-0000-0000-000000000001','ac200000-0000-0000-0000-000000000001','Inbox Hotel','hotel'),('ac300000-0000-0000-0000-000000000002','ac200000-0000-0000-0000-000000000001','Other Inbox','hotel');
insert into public.tenant_memberships(tenant_id,user_id,role) values('ac200000-0000-0000-0000-000000000001','ac100000-0000-0000-0000-000000000001','owner'),('ac200000-0000-0000-0000-000000000001','ac100000-0000-0000-0000-000000000002','member'),('ac200000-0000-0000-0000-000000000001','ac100000-0000-0000-0000-000000000003','member');
insert into public.property_memberships(tenant_id,property_id,user_id) values('ac200000-0000-0000-0000-000000000001','ac300000-0000-0000-0000-000000000001','ac100000-0000-0000-0000-000000000002'),('ac200000-0000-0000-0000-000000000001','ac300000-0000-0000-0000-000000000001','ac100000-0000-0000-0000-000000000003');
insert into public.user_roles(property_id,user_id,role_id) select 'ac300000-0000-0000-0000-000000000001',u,r.id from(values('ac100000-0000-0000-0000-000000000002'::uuid,'front_desk'),('ac100000-0000-0000-0000-000000000003'::uuid,'housekeeping'))v(u,k)join public.roles r on r.key=v.k and r.tenant_id is null;
insert into public.tenants(id,name,slug)values('ac200000-0000-0000-0000-000000000002','Private business','studio-private-business');
insert into public.properties(id,tenant_id,name,property_type)values('ac300000-0000-0000-0000-000000000003','ac200000-0000-0000-0000-000000000002','Private hotel','hotel');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ac100000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select set_config('test.settings','{"portal_origin":"https://stay.example.test","review_url":"https://reviews.example.test/hotel","maps_url":"https://maps.example.test/hotel","website_url":"https://hotel.example.test","hotel_photo_url":"","menu_intro":"Welcome. How can we help?","menu_items":[{"action":"documents","label":"Upload documents","enabled":true},{"action":"reception","label":"Reception","enabled":true}]}',true);
select set_config('test.template','{"name":"booking_welcome","language":"en_US","state":"ready","purpose":"welcome","category":"utility","header_kind":"none","header_text":"","image_url":"","body":"Hello {{guest_name}}, welcome to {{hotel_name}}. View your stay in the secure portal.","footer":"Reply STOP to opt out.","buttons":[{"type":"portal","text":"Open guest portal","action":"documents"}]}',true);
select is((public.whatsapp_studio_workspace('ac300000-0000-0000-0000-000000000001')->>'draft_total')::integer,0,'studio works before API connection or templates exist');
select is(public.whatsapp_studio_workspace('ac300000-0000-0000-0000-000000000001')->'connection_status','null'::jsonb,'no connection is represented accurately');
select throws_ok($$select public.whatsapp_studio_save('ac300000-0000-0000-0000-000000000001',gen_random_uuid(),'template',null,0,current_setting('test.template')::jsonb)$$,'22023',null,'content-reviewed link template requires configured public destination');
select lives_ok($$select public.whatsapp_studio_save('ac300000-0000-0000-0000-000000000001','ac800000-0000-0000-0000-000000000001','settings',null,0,current_setting('test.settings')::jsonb)$$,'owner configures links and menu without API credentials');
select lives_ok($$select public.whatsapp_studio_save('ac300000-0000-0000-0000-000000000001','ac800000-0000-0000-0000-000000000001','settings',null,0,current_setting('test.settings')::jsonb)$$,'repeated settings submission is idempotent despite old version');
select is((select count(*)::integer from public.whatsapp_studio_events where property_id='ac300000-0000-0000-0000-000000000001'),1,'settings retry writes one audit event');
select throws_ok($$select public.whatsapp_studio_save('ac300000-0000-0000-0000-000000000001',gen_random_uuid(),'settings',null,0,current_setting('test.settings')::jsonb)$$,'40001',null,'stale settings edits rejected');
select throws_ok($$select public.whatsapp_studio_save('ac300000-0000-0000-0000-000000000001',gen_random_uuid(),'settings',null,1,current_setting('test.settings')::jsonb||'{"review_url":"javascript:alert(1)"}')$$,'22023',null,'unsafe links rejected at database boundary');
select throws_ok($$select public.whatsapp_studio_save('ac300000-0000-0000-0000-000000000001',gen_random_uuid(),'settings',null,1,current_setting('test.settings')::jsonb||'{"portal_origin":"https://stay.example.test/s/private_token"}')$$,'22023',null,'shared settings cannot store an individual stay URL');
select throws_ok($$select public.whatsapp_studio_save('ac300000-0000-0000-0000-000000000001',gen_random_uuid(),'settings',null,1,current_setting('test.settings')::jsonb||'{"menu_items":[{"action":"reception","label":"One","enabled":true},{"action":"reception","label":"Two","enabled":true}]}')$$,'22023',null,'menu actions cannot be duplicated');
select set_config('test.t',public.whatsapp_studio_save('ac300000-0000-0000-0000-000000000001','ac800000-0000-0000-0000-000000000002','template',null,0,current_setting('test.template')::jsonb)::text,true);
select lives_ok($$select public.whatsapp_studio_save('ac300000-0000-0000-0000-000000000001','ac800000-0000-0000-0000-000000000002','template',null,0,current_setting('test.template')::jsonb)$$,'template creation retries return original template');
select is((select count(*)::integer from public.whatsapp_template_drafts where property_id='ac300000-0000-0000-0000-000000000001'),1,'retry creates no duplicate template');
select is((select count(*)::integer from public.message_templates where property_id='ac300000-0000-0000-0000-000000000001'),0,'reviewed local draft is never provider-approved or synchronized implicitly');
select is((select count(*)::integer from public.messages where property_id='ac300000-0000-0000-0000-000000000001'),0,'studio saves do not enqueue WhatsApp messages');
select throws_ok($$select public.whatsapp_studio_save('ac300000-0000-0000-0000-000000000001','ac800000-0000-0000-0000-000000000002','template',null,0,current_setting('test.template')::jsonb||'{"body":"Changed message content"}')$$,'22023',null,'request cannot be reused for different content');
select throws_ok($$select public.whatsapp_studio_save('ac300000-0000-0000-0000-000000000001',gen_random_uuid(),'template',current_setting('test.t')::uuid,0,current_setting('test.template')::jsonb)$$,'40001',null,'stale template cannot overwrite current content');
select throws_ok($$select public.whatsapp_studio_save('ac300000-0000-0000-0000-000000000001',gen_random_uuid(),'template',current_setting('test.t')::uuid,1,current_setting('test.template')::jsonb||'{"body":"Hello {{passport_number}}, here are the hotel details."}')$$,'22023',null,'unknown body variables rejected');
select throws_ok($$select public.whatsapp_studio_save('ac300000-0000-0000-0000-000000000001',gen_random_uuid(),'template',current_setting('test.t')::uuid,1,current_setting('test.template')::jsonb||'{"body":"Hello {{1}}, here are the hotel details."}')$$,'22023',null,'numbered or malformed variables rejected in named-variable authoring');
select throws_ok($$select public.whatsapp_studio_save('ac300000-0000-0000-0000-000000000001',gen_random_uuid(),'template',current_setting('test.t')::uuid,1,current_setting('test.template')::jsonb||'{"footer":"Hello {{guest_name}}"}')$$,'22023',null,'footer variables cannot bypass static footer requirements');
select throws_ok($$select public.whatsapp_studio_save('ac300000-0000-0000-0000-000000000001',gen_random_uuid(),'template',current_setting('test.t')::uuid,1,current_setting('test.template')::jsonb||'{"header_kind":"image","image_url":"file:///private.jpg"}')$$,'22023',null,'nonpublic photo links rejected');
select throws_ok($$select public.whatsapp_studio_save('ac300000-0000-0000-0000-000000000001',gen_random_uuid(),'template',current_setting('test.t')::uuid,1,current_setting('test.template')::jsonb||'{"buttons":[{"type":"portal","text":"Portal","action":"stay"},{"type":"quick_reply","text":"MENU","action":"menu"}]}')$$,'22023',null,'unsupported mixed button composition rejected');
select set_config('test.journey',jsonb_build_object('event','booking_created','template_id',current_setting('test.t'),'sources',jsonb_build_array('ota'),'delay_minutes',0,'prepared',true)::text,true);
select lives_ok($$select public.whatsapp_studio_save('ac300000-0000-0000-0000-000000000001','ac800000-0000-0000-0000-000000000003','journey',null,0,current_setting('test.journey')::jsonb)$$,'owner prepares OTA booking welcome plan');
select is((select count(*)::integer from public.messages where property_id='ac300000-0000-0000-0000-000000000001'),0,'prepared plan still sends nothing');
select throws_ok($$select public.whatsapp_studio_save('ac300000-0000-0000-0000-000000000001',gen_random_uuid(),'journey',null,0,current_setting('test.journey')::jsonb||'{"event":"checked_out"}')$$,'22023',null,'journey event requires matching template purpose');
select throws_ok($$select public.whatsapp_studio_save('ac300000-0000-0000-0000-000000000002',gen_random_uuid(),'journey',null,0,current_setting('test.journey')::jsonb)$$,'22023',null,'journey cannot reference a template from another hotel');
select throws_ok($$select public.whatsapp_studio_save('ac300000-0000-0000-0000-000000000001',gen_random_uuid(),'template',current_setting('test.t')::uuid,1,current_setting('test.template')::jsonb||'{"state":"archived"}')$$,'22023',null,'prepared journey protects its linked template from accidental archiving');
select is((public.whatsapp_studio_workspace('ac300000-0000-0000-0000-000000000002')->>'total')::integer,0,'hotel library stays isolated');
select throws_ok($$select public.whatsapp_studio_workspace('ac300000-0000-0000-0000-000000000003')$$,'42501',null,'unrelated business metadata denied');
select is(jsonb_array_length(public.whatsapp_studio_workspace('ac300000-0000-0000-0000-000000000001','{"q":"BOOKING"}')->'templates'),1,'template search ignores case');
select is(jsonb_array_length(public.whatsapp_studio_workspace('ac300000-0000-0000-0000-000000000001','{"page":2}')->'templates'),0,'template directory pagination is bounded');
select is((public.workspace_permissions('ac300000-0000-0000-0000-000000000001')->>'guest_messaging')::boolean,true,'owner navigation includes offline preparation');
select set_config('request.jwt.claims','{"sub":"ac100000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select is((public.whatsapp_studio_workspace('ac300000-0000-0000-0000-000000000001')->>'can_manage')::boolean,false,'front desk can inspect templates without changing hotel configuration');
select throws_ok($$select public.whatsapp_studio_save('ac300000-0000-0000-0000-000000000001',gen_random_uuid(),'settings',null,1,current_setting('test.settings')::jsonb)$$,'42501',null,'front desk cannot bypass configuration permission with RPC');
select set_config('request.jwt.claims','{"sub":"ac100000-0000-0000-0000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.whatsapp_studio_workspace('ac300000-0000-0000-0000-000000000001')$$,'42501',null,'housekeeping cannot inspect WhatsApp configuration');
select is_empty($$select 1 from public.whatsapp_template_drafts$$,'draft RLS excludes unauthorized roles');
reset role;
select ok(not has_function_privilege('anon','public.whatsapp_studio_save(uuid,uuid,text,uuid,integer,jsonb)','execute'),'anonymous cannot configure templates');
select ok(not has_table_privilege('authenticated','private.whatsapp_studio_commands','select'),'internal command payloads are private');
update public.tenants set status='suspended'where id='ac200000-0000-0000-0000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ac100000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.whatsapp_studio_workspace('ac300000-0000-0000-0000-000000000001')$$,'42501',null,'suspended business cannot use studio read models');
select throws_ok($$select public.whatsapp_studio_save('ac300000-0000-0000-0000-000000000001',gen_random_uuid(),'settings',null,1,current_setting('test.settings')::jsonb)$$,'42501',null,'suspended business cannot save preparation forms');
reset role;
update public.tenants set status='active'where id='ac200000-0000-0000-0000-000000000001';
set local role authenticated;
select throws_ok($$select public.whatsapp_studio_save('ac300000-0000-0000-0000-000000000001',gen_random_uuid(),'template',current_setting('test.t')::uuid,1,current_setting('test.template')::jsonb||'{"body":12345678901234}')$$,'22023',null,'numeric JSON body cannot corrupt the template editor');
select throws_ok($$select public.whatsapp_studio_save('ac300000-0000-0000-0000-000000000001',gen_random_uuid(),'template',current_setting('test.t')::uuid,1,current_setting('test.template')::jsonb||'{"buttons":[{"type":"portal","text":{"a":1},"action":"stay"}]}')$$,'22023',null,'object button labels rejected before persistence');
select * from finish();
rollback;
